window.docContents[173].resolve({"/Types-and-expressions/Variable/#Core-C______--Types-and-expressions--Variable":{"contents":"The variable denotes the location the environment assigns to it. The store does not change. The other location denoting expressions, *e, e.f, e->f and e[i], are the nodes of the second half of this chapter.The implementations are partial, so Lean records opaque constants that carry the type and not the body, and no property of them is proved here.\n\nReading  is reading . The location must be live.The implementations are partial, so Lean records opaque constants that carry the type and not the body, and no property of them is proved here.\n\n","context":"Core C++\u0009Types and expressions","header":"3.2. Variable","id":"/Types-and-expressions/Variable/#Core-C______--Types-and-expressions--Variable"}});